            "zh-TW": "\u6C23\u70B8\u934B\u5C0F\u70E4\u76E4\u5237\u6CB9\uFF0C\u6253\u5165\u96DE\u86CB\uFF0C\u4EE5 200\xB0C \u6C23\u70B8 3.5-4 \u5206\u9418\uFF0C\u540C\u6A23\u80FD\u9054\u5230\u86CB\u767D\u9165\u8106\u3001\u86CB\u9EC3\u6D41\u5FC3\u7684\u6548\u679C\uFF01",
