            "ja": "\u30CE\u30F3\u30D5\u30E9\u30A4\u30E4\u30FC\u306E\u8010\u71B1\u76BF\u306B\u6CB9\u3092\u5857\u308A\u3001200\u2103\u3067\u7D044\u5206\u52A0\u71B1\u3059\u308B\u3068\u30AB\u30EA\u30AB\u30EA\u534A\u719F\u76EE\u7389\u713C\u304D\u304C\u5B8C\u6210\u3057\u307E\u3059\u3002",
            "ko": "\uC5D0\uC5B4\uD504\uB77C\uC774\uC5B4 \uC804\uC6A9 \uC6A9\uAE30\uC5D0 \uAE30\uB984\uC744 \uBC14\uB974\uACE0 \uB2EC\uAC40\uC744 \uAE68 \uB123\uC5B4 200\uB3C4\uC5D0\uC11C 4\uBD84\uAC04 \uB3CC\uB9AC\uBA74 \uBC14\uC0AD\uD55C \uBC18\uC219 \uD6C4\uB77C\uC774\uAC00 \uB429\uB2C8\uB2E4."
