    "ja": "\u8339\u3067\u9EBA\u3068\u30B5\u30AF\u30B5\u30AF\u63DA\u3052\u9EBA\u306E\u4E8C\u91CD\u594F\u3002\u30B3\u30B3\u30CA\u30C3\u30C4\u30DF\u30EB\u30AF\u4ED5\u7ACB\u3066\u306E\u5965\u6DF1\u3044\u30B9\u30D1\u30A4\u30B9\u30B9\u30FC\u30D7",
