      "ja": "19\u4E16\u7D00\u672B\u306E\u30BF\u30A4\u738B\u5BA4\u5BAE\u5EF7\u6599\u7406\u96C6\u306B\u8A18\u3055\u308C\u305F\u6B74\u53F2\u3042\u308B\u30B9\u30FC\u30D7\u3002\u300C\u30AB\u30FC\u300D\u306F\u5357\u8591\uFF08\u30AC\u30E9\u30F3\u30AC\u30EB\uFF09\u3092\u6307\u3057\u3001\u751F\u59DC\u3068\u306F\u4E00\u7DDA\u3092\u753B\u3059\u30A6\u30C3\u30C7\u30A3\u3067\u9AD8\u8CB4\u306A\u6E05\u6DBC\u611F\u3092\u6301\u3061\u307E\u3059\u3002\u30B3\u30B3\u30CA\u30C3\u30C4\u30DF\u30EB\u30AF\u306E\u30AF\u30EA\u30FC\u30DF\u30FC\u3055\u3068\u30E9\u30A4\u30E0\u679C\u6C41\u306E\u7A4F\u3084\u304B\u306A\u9178\u5473\u304C\u7D76\u5999\u306B\u8ABF\u548C\u3057\u307E\u3059\u3002",
      "ko": "19\uC138\uAE30 \uB9D0 \uB77C\uB9C8 5\uC138 \uC655\uC2E4 \uC694\uB9AC\uCC45\uC5D0 \uCC98\uC74C \uB4F1\uC7A5\uD588\uC2B5\uB2C8\uB2E4. '\uCE74'\uB294 \uC774 \uC694\uB9AC\uC758 \uC8FC\uC778\uACF5\uC778 \uAC08\uB791\uAC08(\uC0DD\uAC15\uACFC \uC2DD\uBB3C)\uC744 \uC758\uBBF8\uD558\uBA70, \uB9E4\uC6B4\uB9DB\uBCF4\uB2E4\uB294 \uC194\uC78E\uACFC \uC2DC\uD2B8\uB7EC\uC2A4 \uD5A5\uC744 \uB0C5\uB2C8\uB2E4. \uBD80\uB4DC\uB7EC\uC6B4 \uCF54\uCF54\uB11B \uBC00\uD06C\uAC00 \uC704\uC7A5\uC744 \uB530\uB73B\uD558\uAC8C \uB2EC\uB798\uC90D\uB2C8\uB2E4."
