        "th": "\u0E04\u0E25\u0E38\u0E01\u0E40\u0E2A\u0E49\u0E19\u0E43\u0E2B\u0E0D\u0E48\u0E01\u0E31\u0E1A\u0E0B\u0E35\u0E2D\u0E34\u0E4A\u0E27\u0E14\u0E33\u0E2B\u0E27\u0E32\u0E19\u0E01\u0E48\u0E2D\u0E19\u0E1C\u0E31\u0E14",
