    "ja": "\u30BF\u30A4\u5168\u571F\u304C\u8A8D\u3081\u308B\u30D5\u30E9\u30A4\u30C9\u30C1\u30AD\u30F3\u306E\u6700\u9AD8\u5CF0\u3002\u565B\u3093\u3060\u77AC\u9593\u3001\u8089\u6C41\u304C\u5F3E\u3051\u98DB\u3076",
    "ko": "\uD0DC\uAD6D \uC804\uC5ED\uC5D0\uC11C \uC190\uAF3D\uD788\uB294 \uBC14\uC0AD\uD568\uACFC \uC721\uC999\uC758 \uB05D\uD310\uC655 \uCE58\uD0A8"
