        "th": "\u0E44\u0E01\u0E48\u0E17\u0E2D\u0E14\u0E40\u0E08\u0E4A\u0E2B\u0E07\u0E29\u0E4C \u0E0B\u0E2D\u0E22\u0E42\u0E1B\u0E42\u0E25",
        "ja": "\u30DD\u30ED\u30FB\u30D5\u30E9\u30A4\u30C9\u30C1\u30AD\u30F3\uFF08\u30BD\u30A4\u30FB\u30DD\u30ED\uFF09",
