    "ja": "\u30AB\u30AA\u30FB\u30AB\u30FC\u30E0\u30FC\uFF08\u3068\u308D\u3068\u308D\u716E\u8FBC\u307F\u8C5A\u8DB3\u3054\u98EF\uFF09",
