      "th": "\u0E2A\u0E39\u0E15\u0E23\u0E40\u0E14\u0E47\u0E14\u0E0A\u0E32\u0E27\u0E27\u0E31\u0E07: \u0E43\u0E2A\u0E48\u0E02\u0E49\u0E32\u0E27\u0E2A\u0E27\u0E22\u0E2B\u0E2D\u0E21\u0E21\u0E30\u0E25\u0E34\u0E2A\u0E38\u0E01\u0E1B\u0E31\u0E48\u0E19\u0E23\u0E27\u0E21\u0E01\u0E31\u0E1A\u0E41\u0E1B\u0E49\u0E07 \u0E08\u0E30\u0E0A\u0E48\u0E27\u0E22\u0E43\u0E2B\u0E49\u0E40\u0E1B\u0E25\u0E37\u0E2D\u0E01\u0E02\u0E19\u0E21\u0E01\u0E23\u0E2D\u0E1A\u0E19\u0E38\u0E48\u0E21 \u0E44\u0E21\u0E48\u0E41\u0E02\u0E47\u0E07\u0E01\u0E23\u0E30\u0E14\u0E49\u0E32\u0E07 \u0E40\u0E04\u0E35\u0E49\u0E22\u0E27\u0E40\u0E1E\u0E25\u0E34\u0E19\u0E25\u0E30\u0E21\u0E38\u0E19\u0E25\u0E34\u0E49\u0E19",
      "ja": "\u4E09\u4EE3\u7D9A\u304F\u540D\u5E97\u306E\u79D8\u5BC6\uFF1A\u751F\u306E\u7C73\u7C89\u3060\u3051\u3067\u306A\u304F\u300E\u708A\u3044\u305F\u3054\u98EF\u300F\u3092\u5C11\u3057\u6DF7\u305C\u3066\u30DF\u30AD\u30B5\u30FC\u306B\u304B\u3051\u308B\u306E\u304C\u6975\u610F\uFF01\u51B7\u3081\u3066\u3082\u30AB\u30C1\u30AB\u30C1\u306B\u306A\u3089\u305A\u3001\u3082\u3063\u3061\u308A\u3068\u3057\u305F\u6975\u4E0A\u306E\u6B6F\u3054\u305F\u3048\u304C\u751F\u307E\u308C\u307E\u3059\uFF01",
      "ko": "\uBC29\uCF55 3\uB300 \uC804\uD1B5 \uB178\uC810\uC758 \uBE44\uBC95: \uBC18\uC8FD\uC5D0 '\uC9C0\uC740 \uBC25'\uC744 \uC870\uAE08 \uB123\uC5B4 \uD568\uAED8 \uAC08\uC544\uBCF4\uC138\uC694! \uC775\uC740 \uBC25\uC758 \uC804\uBD84\uC774 \uAC89\uC740 \uBC14\uC0AD\uD558\uBA74\uC11C\uB3C4 \uC18D\uC740 \uCAC0\uB4DD\uD55C \uB9C8\uC131\uC758 \uC2DD\uAC10\uC744 \uB9CC\uB4E4\uC5B4 \uB0C5\uB2C8\uB2E4!"
