          "ja": "\u4E7E\u71E5\u9EBA\u3092\u4F7F\u3046\u5834\u5408\u306F\u5B8C\u5168\u306B\u6C34\u6C17\u3092\u62ED\u304D\u53D6\u3063\u3066\u304B\u3089\u7092\u3081\u306A\u3044\u3068\u7126\u3052\u76EE\u304C\u3064\u304D\u307E\u305B\u3093\u3002",
          "ko": "\uAC74\uBA74\uC740 \uBB3C\uAE30\uB97C \uD0A4\uCE5C\uD0C0\uC6D4\uB85C \uC644\uC804\uD788 \uB2E6\uC544\uB0B4\uC57C \uC6CD\uC5D0\uC11C \uBC14\uC0AD\uD558\uAC8C \uB20C\uB7EC\uBD99\uC2B5\uB2C8\uB2E4."
