        "th": "\u0E19\u0E49\u0E33\u0E08\u0E34\u0E49\u0E21\u0E1A\u0E4A\u0E27\u0E22\u0E40\u0E08\u0E35\u0E48\u0E22\u0E2B\u0E27\u0E32\u0E19\u0E2D\u0E21\u0E40\u0E1B\u0E23\u0E35\u0E49\u0E22\u0E27",
