          "th": "\u0E19\u0E49\u0E33\u0E08\u0E34\u0E49\u0E21\u0E44\u0E01\u0E48\u0E1C\u0E2A\u0E21\u0E19\u0E49\u0E33\u0E2A\u0E49\u0E21\u0E2A\u0E32\u0E22\u0E0A\u0E39",
          "ja": "\u30B9\u30A4\u30FC\u30C8\u30C1\u30EA\u30BD\u30FC\u30B9\uFF0B\u30EC\u30E2\u30F3\u6C41\u5C11\u3005",
